/** No images, canvas, DOM, shader injection, or runtime downloads. */
function surfaceMaps(kind: 'stone' | 'leather' | 'bone'): { map: THREE.DataTexture; bumpMap: THREE.DataTexture } {
  const size = kind === 'stone' ? 768 : 256;
